CREATE DATABASE IF NOT EXISTS mas_tu_vu CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mas_tu_vu;
CREATE TABLE IF NOT EXISTS admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contenus (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, titre VARCHAR(180) NOT NULL, description TEXT NULL, type ENUM('publicite','bande_annonce','actualite') NOT NULL DEFAULT 'publicite', media_type ENUM('image','video','youtube') NOT NULL, fichier VARCHAR(255) NULL, video_url VARCHAR(500) NULL, publie TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_publication (publie, created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tickets (type ENUM('GP','VIP','VVIP') PRIMARY KEY, prix INT UNSIGNED NOT NULL, stock_initial INT UNSIGNED NOT NULL, stock_restant INT UNSIGNED NOT NULL, vendus INT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB;
INSERT IGNORE INTO tickets(type,prix,stock_initial,stock_restant,vendus) VALUES ('GP',3000,100,100,0),('VIP',10000,50,50,0),('VVIP',20000,20,20,0);
